  @override
  String get legalDisclaimerAINotLawyerBody =>
      'ಅಂಬ್ರೆಲಾದ AI ವ್ಯವಸ್ಥೆಗಳು ಸಾಮಾನ್ಯ ಕಾನೂನು ಕಾರ್ಪೋರಾದಲ್ಲಿ ತರಬೇತಿ ಪಡೆದ ದೊಡ್ಡ ಭಾಷಾ ಮಾದರಿಗಳಾಗಿವೆ. ಅವರು ಅಭ್ಯಾಸ ಪ್ರಮಾಣಪತ್ರಗಳನ್ನು ಹೊಂದಿಲ್ಲ, ನ್ಯಾಯಾಲಯದಲ್ಲಿ ಹಾಜರಾಗಲು ಸಾಧ್ಯವಿಲ್ಲ, ಯಾವುದೇ ಬಾರ್ ಅಸೋಸಿಯೇಷನ್ ​​ಅಥವಾ ಕಾನೂನು ಸೊಸೈಟಿಯಿಂದ ನಿಯಂತ್ರಿಸಲ್ಪಡುವುದಿಲ್ಲ ಮತ್ತು ವಕೀಲರು ನಿಮಗೆ ಕಾಳಜಿಯ ಕರ್ತವ್ಯವನ್ನು ಹೊಂದಿರುವುದಿಲ್ಲ. AI ಔಟ್‌ಪುಟ್‌ಗಳು: ವಾಸ್ತವಿಕ ದೋಷಗಳು ಅಥವಾ ಭ್ರಮೆಗಳನ್ನು ಹೊಂದಿರಬಹುದು; ನಿಮ್ಮ ನಿರ್ದಿಷ್ಟ ಸಂಗತಿಗಳಿಗೆ ಸಂಬಂಧಿಸಿದ ವಸ್ತು ಪರಿಗಣನೆಗಳನ್ನು ಬಿಟ್ಟುಬಿಡಿ; ತಿದ್ದುಪಡಿ ಮಾಡಿದ, ರದ್ದುಪಡಿಸಿದ ಅಥವಾ ರದ್ದುಗೊಳಿಸಲಾದ ಕಾನೂನುಗಳು ಅಥವಾ ಪ್ರಕರಣಗಳನ್ನು ಉಲ್ಲೇಖಿಸಿ; ಇತ್ತೀಚಿನ ಶಾಸಕಾಂಗ ಬದಲಾವಣೆಗಳನ್ನು ಗಣನೆಗೆ ತೆಗೆದುಕೊಳ್ಳಲು ವಿಫಲವಾಗಿದೆ; ಮತ್ತು ಸಂಕೀರ್ಣ ಅಥವಾ ಅಸ್ಪಷ್ಟ ಕಾನೂನು ಪ್ರಶ್ನೆಗಳನ್ನು ತಪ್ಪಾಗಿ ಅರ್ಥೈಸಿಕೊಳ್ಳಿ. ನೀವು ಪ್ರತಿ AI ಔಟ್‌ಪುಟ್ ಅನ್ನು ವಿಚಾರಣೆಗೆ ಆರಂಭಿಕ ಹಂತವಾಗಿ ಪರಿಗಣಿಸಬೇಕು, ಅಂತಿಮ ಉತ್ತರವಲ್ಲ.';

  @override
  String get legalDisclaimerAINotLawyerHeading => '3. AI ವಕೀಲರಲ್ಲ';

  @override
  String get legalDisclaimerCitationBody =>
      'ಅಂಬ್ರೆಲಾ ಕಾನೂನು, ನಿಯಂತ್ರಣ, ನಿಯಮ ಅಥವಾ ನ್ಯಾಯಾಂಗ ನಿರ್ಧಾರವನ್ನು ಉಲ್ಲೇಖಿಸಿದಾಗ, ನೀವು ಸ್ವತಂತ್ರವಾಗಿ ಪರಿಶೀಲಿಸಬೇಕು: (ಎ) ಉಲ್ಲೇಖಿಸಿದ ಮೂಲವು ಅಸ್ತಿತ್ವದಲ್ಲಿದೆ; (ಬಿ) ಉಲ್ಲೇಖವು ನಿಖರವಾಗಿದೆ (ವಿಭಾಗ, ಉಪವಿಭಾಗ ಮತ್ತು ವರ್ಷ); (ಸಿ) ಮೂಲವು ಪ್ರಸ್ತುತ ಜಾರಿಯಲ್ಲಿದೆ ಮತ್ತು ಅದನ್ನು ತಿದ್ದುಪಡಿ ಮಾಡಲಾಗಿಲ್ಲ ಅಥವಾ ರದ್ದುಗೊಳಿಸಲಾಗಿಲ್ಲ; (ಡಿ) ಉಲ್ಲೇಖಿಸಿದ ಪಠ್ಯವು ಮೂಲವನ್ನು ನಿಖರವಾಗಿ ಪ್ರತಿಬಿಂಬಿಸುತ್ತದೆ. AI ಉಲ್ಲೇಖ ದೋಷಗಳು - ಫ್ಯಾಬ್ರಿಕೇಟೆಡ್ ಉಲ್ಲೇಖಗಳು ಸೇರಿದಂತೆ - ಎಲ್ಲಾ ಪ್ರಸ್ತುತ AI ವ್ಯವಸ್ಥೆಗಳ ತಿಳಿದಿರುವ ಮಿತಿಯಾಗಿದೆ. ಸ್ವತಂತ್ರ ಪರಿಶೀಲನೆಯಿಲ್ಲದೆ ಕಾನೂನು ಪ್ರಕ್ರಿಯೆಗಳು, ಸಲಹೆಗಳು ಅಥವಾ ಫೈಲಿಂಗ್‌ಗಳಲ್ಲಿನ ಉಲ್ಲೇಖವನ್ನು ಎಂದಿಗೂ ಅವಲಂಬಿಸಬೇಡಿ.';

  @override
  String get legalDisclaimerCitationHeading => 'AI ಉಲ್ಲೇಖ ನಿಯಮ';

  @override
  String get legalDisclaimerJurisdictionBody =>
      'ಭಾರತ: AI ವಿಶ್ಲೇಷಣೆಯು ಕೇಂದ್ರ ಶಾಸನ, ನಿರ್ದಿಷ್ಟಪಡಿಸಿದ ರಾಜ್ಯ ಕಾಯಿದೆಗಳು ಮತ್ತು ನ್ಯಾಯಾಂಗ ನಿರ್ಧಾರಗಳನ್ನು ಆಧರಿಸಿದೆ. ಇದು ಜಿಲ್ಲಾ ನ್ಯಾಯಾಲಯದ ಮಟ್ಟದ ಅಭ್ಯಾಸ, ಸ್ಥಳೀಯ ಬಾರ್ ಕಸ್ಟಮ್ಸ್ ಅಥವಾ ಕ್ರೋಡೀಕರಿಸದ ಕಾರ್ಯವಿಧಾನದ ನಿಯಮಗಳನ್ನು ಪರಿಗಣಿಸುವುದಿಲ್ಲ. ಯುನೈಟೆಡ್ ಸ್ಟೇಟ್ಸ್: AI ವಿಶ್ಲೇಷಣೆಯು ಫೆಡರಲ್ ಕಾನೂನು ಮತ್ತು ಆಯ್ದ ರಾಜ್ಯದ ಕಾನೂನನ್ನು ಆಧರಿಸಿದೆ. US ಕಾನೂನು ವಿಶ್ಲೇಷಣೆಯು ರಾಜ್ಯ-ನಿರ್ದಿಷ್ಟ ಪರವಾನಗಿ ಪಡೆದ ಸಲಹೆಗಾರರಿಗೆ ಬದಲಿಯಾಗಿಲ್ಲ. ಪರಿಶೀಲಿಸಿದ ವಕೀಲರ ಪರಿಶೀಲನೆಯಿಲ್ಲದೆ ವಲಸೆ, ಕ್ರಿಮಿನಲ್ ರಕ್ಷಣೆ ಅಥವಾ ತೆರಿಗೆ ವಿಷಯಗಳಿಗೆ ಲಭ್ಯವಿಲ್ಲ. ಕೀನ್ಯಾ: ವಿಶ್ಲೇಷಣೆಯು ಕೀನ್ಯಾದ ಶಾಸನಗಳು, ಅಂಗಸಂಸ್ಥೆ ಶಾಸನಗಳು ಮತ್ತು ಪ್ರಕಟಿತ ಉಚ್ಚ ನ್ಯಾಯಾಲಯ ಮತ್ತು ಮೇಲ್ಮನವಿ ನ್ಯಾಯಾಲಯದ ನಿರ್ಧಾರಗಳನ್ನು ಸೆಳೆಯುತ್ತದೆ. ಇದು ಸಾಂಪ್ರದಾಯಿಕ ಕಾನೂನು, ಮ್ಯಾಜಿಸ್ಟ್ರೇಟ್ ನ್ಯಾಯಾಲಯದ ವ್ಯತ್ಯಾಸಗಳು ಅಥವಾ ಅಪ್ರಕಟಿತ ತೀರ್ಪುಗಳಿಗೆ ಕಾರಣವಾಗುವುದಿಲ್ಲ. ಯುನೈಟೆಡ್ ಕಿಂಗ್‌ಡಮ್: ವಿಶ್ಲೇಷಣೆಯು ಇಂಗ್ಲಿಷ್ ಮತ್ತು ವೆಲ್ಷ್ ಕಾನೂನನ್ನು ಒಳಗೊಂಡಿದೆ. ಸ್ಕಾಟ್ಸ್ ಕಾನೂನು, ಉತ್ತರ ಐರಿಶ್ ಕಾನೂನು, ಮತ್ತು ಹಂಚಿಕೆಯ ವಿಷಯಗಳು ಗಮನಾರ್ಹವಾಗಿ ಭಿನ್ನವಾಗಿರಬಹುದು; ನ್ಯಾಯವ್ಯಾಪ್ತಿ-ನಿರ್ದಿಷ್ಟ ಸಲಹೆಯನ್ನು ಪಡೆಯಿರಿ.';

  @override
  String get legalDisclaimerJurisdictionHeading => '8. ನ್ಯಾಯವ್ಯಾಪ್ತಿಯ ಮಿತಿಗಳು';

  @override
  String get legalDisclaimerLawyerReviewBody =>
      'ವಕೀಲರು-ಪರಿಶೀಲಿಸಿದ ವರದಿಗಳು ಮತ್ತು ಕಾರ್ಯತಂತ್ರದ ಮೆಮೊಗಳು ಔಪಚಾರಿಕ ಕಾನೂನು ಸಲಹೆಯಾಗಿ ಅವಲಂಬಿಸುವ ಮೊದಲು ಮಾನವ ವಕೀಲರ ಅನುಮೋದನೆಯ ಅಗತ್ಯವಿರುತ್ತದೆ.';

