  @override
  String get legalDisclaimerNoPrivilegeBody =>
      'ಅಂಬ್ರೆಲ್ಲಾದ AI ಯೊಂದಿಗಿನ ಸಂವಹನಗಳನ್ನು ಯಾವುದೇ ನ್ಯಾಯವ್ಯಾಪ್ತಿಯಲ್ಲಿ ವಕೀಲ-ಕ್ಲೈಂಟ್ ಸವಲತ್ತು ಅಥವಾ ಕಾನೂನು ವೃತ್ತಿಪರ ಸವಲತ್ತುಗಳಿಂದ ರಕ್ಷಿಸಲಾಗಿಲ್ಲ. ನೀವು ಸವಲತ್ತು ಅಡಿಯಲ್ಲಿ ರಕ್ಷಿಸಲು ಉದ್ದೇಶಿಸಿರುವ ವೇದಿಕೆಗೆ ಮಾಹಿತಿಯನ್ನು ಸಲ್ಲಿಸಬೇಡಿ. ಅಂಬ್ರೆಲ್ಲಾ ಮಾರುಕಟ್ಟೆಯ ಮೂಲಕ ನೀವು ಪರವಾನಗಿ ಪಡೆದ ವಕೀಲರನ್ನು ತೊಡಗಿಸಿಕೊಂಡರೆ, ಕಾರ್ಯಗತಗೊಳಿಸಿದ ಧಾರಕ ಒಪ್ಪಂದದ ಅಡಿಯಲ್ಲಿ ಆ ವಕೀಲರೊಂದಿಗಿನ ನಿಮ್ಮ ಸಂವಹನಗಳಿಗೆ ವಿಶೇಷ ಸೌಲಭ್ಯವನ್ನು ಲಗತ್ತಿಸಬಹುದು, ಆದರೆ ನಿಮ್ಮ ಹಿಂದಿನ AI ಸಂವಹನಗಳಿಗೆ ಅಲ್ಲ.';

