  @override
  String get legalDisclaimerRegulatoryBody =>
      'DVTech ವೆಂಚರ್ಸ್ ಒಂದು ತಂತ್ರಜ್ಞಾನ ಕಂಪನಿಯಾಗಿದೆ, ನಿಯಂತ್ರಿತ ಕಾನೂನು ಸೇವೆ ಒದಗಿಸುವವರಲ್ಲ. ಕಾನೂನು ಸೇವೆಗಳನ್ನು ಒದಗಿಸಲು ಸಾಲಿಸಿಟರ್ಸ್ ರೆಗ್ಯುಲೇಶನ್ ಅಥಾರಿಟಿ (UK), ಬಾರ್ ಕೌನ್ಸಿಲ್ ಆಫ್ ಇಂಡಿಯಾ, ಲಾ ಸೊಸೈಟಿ ಆಫ್ ಕೀನ್ಯಾ, ಯಾವುದೇ US ಸ್ಟೇಟ್ ಬಾರ್ ಅಥವಾ ಯಾವುದೇ ಇತರ ಕಾನೂನು ನಿಯಂತ್ರಣ ಸಂಸ್ಥೆಯಿಂದ ನಮಗೆ ಅಧಿಕಾರವಿಲ್ಲ. ಅಂಬ್ರೆಲಾ ಪ್ಲಾಟ್‌ಫಾರ್ಮ್ ಕಾನೂನು ಸೇವೆಗಳ ಕಾಯಿದೆ 2007 (ಯುಕೆ) ಅಥವಾ ಇತರ ನ್ಯಾಯವ್ಯಾಪ್ತಿಗಳಲ್ಲಿ ಸಮಾನವಾದ ಶಾಸನದಲ್ಲಿ ವ್ಯಾಖ್ಯಾನಿಸಲಾದ ನಿಯಂತ್ರಿತ ಕಾನೂನು ಚಟುವಟಿಕೆಯನ್ನು ಒದಗಿಸುವುದಿಲ್ಲ.';

  @override
  String get legalDisclaimerRegulatoryHeading => '9. ನಿಯಂತ್ರಕ ಸ್ಥಿತಿ';

  @override
  String get legalDisclaimerRelianceBody =>
      'ನೀವು ಇದನ್ನು ಅಂಗೀಕರಿಸುತ್ತೀರಿ: (a) ನಿಮ್ಮ ಕಾನೂನು ಹಕ್ಕುಗಳು ಅಥವಾ ಕಟ್ಟುಪಾಡುಗಳ ಮೇಲೆ ಪರಿಣಾಮ ಬೀರುವ ನಿರ್ಧಾರಗಳನ್ನು ತೆಗೆದುಕೊಳ್ಳಲು ನೀವು AI ಔಟ್‌ಪುಟ್‌ಗಳನ್ನು ಮಾತ್ರ ಅವಲಂಬಿಸುವುದಿಲ್ಲ; (ಬಿ) ಕಾನೂನು ಪ್ರಕ್ರಿಯೆಗಳನ್ನು ಪ್ರಾರಂಭಿಸುವ, ಸಮರ್ಥಿಸುವ ಅಥವಾ ಇತ್ಯರ್ಥಗೊಳಿಸುವ ಮೊದಲು ನೀವು ಸ್ವತಂತ್ರ ಅರ್ಹ ಕಾನೂನು ಸಲಹೆಯನ್ನು ಪಡೆಯುತ್ತೀರಿ; (ಸಿ) ಸ್ವತಂತ್ರ ಪರಿಶೀಲನೆಯಿಲ್ಲದೆ AI ಔಟ್‌ಪುಟ್‌ಗಳ ಮೇಲೆ ನಿಮ್ಮ ಅವಲಂಬನೆಯಿಂದ ಉಂಟಾಗುವ ಯಾವುದೇ ಹಾನಿಗೆ DVTech ವೆಂಚರ್ಸ್ ಜವಾಬ್ದಾರನಾಗಿರುವುದಿಲ್ಲ. ಈ ಮಿತಿಯು ಅನ್ವಯವಾಗುವ ಕಾನೂನಿನಿಂದ ಅನುಮತಿಸಲಾದ ಪೂರ್ಣ ಪ್ರಮಾಣದಲ್ಲಿ ಅನ್ವಯಿಸುತ್ತದೆ.';

  @override
  String get legalDisclaimerRelianceHeading => '6. ಅವಲಂಬನೆಯ ಮೇಲಿನ ಮಿತಿ';

  @override
  String get legalDisclaimerScopeBody =>
      'ಈ ಹಕ್ಕು ನಿರಾಕರಣೆ ಅಂಬ್ರೆಲಾ ಪ್ಲಾಟ್‌ಫಾರ್ಮ್‌ನ ಪ್ರತಿಯೊಂದು ವೈಶಿಷ್ಟ್ಯಕ್ಕೂ ಅನ್ವಯಿಸುತ್ತದೆ, ಆದರೆ ಇವುಗಳಿಗೆ ಸೀಮಿತವಾಗಿಲ್ಲ: ಕಾನೂನು ಸಮಸ್ಯೆ ಪರೀಕ್ಷಕ, AI ಕಾಪಿಲಟ್, ಡಾಕ್ಯುಮೆಂಟ್ ವಿಮರ್ಶೆ, ಕಾನೂನು ಸಂಶೋಧನೆ, ವಿಷಯ ವಿಶ್ಲೇಷಣೆ, ತಂತ್ರದ ಮೆಮೊಗಳು, ಕರಡು ದಾಖಲೆಗಳು ಮತ್ತು ಯಾವುದೇ ಇತರ AI- ರಚಿತವಾದ ವಿಷಯ. ಇದು ಎಲ್ಲಾ ಬಳಕೆದಾರರಿಗೆ ಅನ್ವಯಿಸುತ್ತದೆ - ಗ್ರಾಹಕರು, ವಕೀಲರು ಬಳಕೆದಾರರು ಮತ್ತು ಕಾನೂನು ಸಂಸ್ಥೆಯ ಬಾಡಿಗೆದಾರರು - ಅಂಬ್ರೆಲಾ ಕಾರ್ಯನಿರ್ವಹಿಸುವ ಎಲ್ಲಾ ನ್ಯಾಯವ್ಯಾಪ್ತಿಯಲ್ಲಿ (ಭಾರತ, ಯುನೈಟೆಡ್ ಸ್ಟೇಟ್ಸ್, ಕೀನ್ಯಾ ಮತ್ತು ಯುನೈಟೆಡ್ ಕಿಂಗ್‌ಡಮ್).';

  @override
  String get legalDisclaimerScopeHeading => '1. ಈ ಹಕ್ಕು ನಿರಾಕರಣೆ ವ್ಯಾಪ್ತಿ';

  @override
  String get legalDisclaimerUniversalBody =>
      'ಅಂಬ್ರೆಲಾ ಕಾನೂನು ಮಾಹಿತಿ, ದಾಖಲೆ ವಿವರಣೆ, ಸಮಸ್ಯೆ ಗುರುತಿಸುವಿಕೆ ಮತ್ತು ಅಪಾಯದ ವಿಶ್ಲೇಷಣೆಯನ್ನು ಒದಗಿಸುತ್ತದೆ. ಇದು ಕಾನೂನು ಸಂಸ್ಥೆಯಲ್ಲ ಮತ್ತು ಪರವಾನಗಿ ಪಡೆದ ವಕೀಲರನ್ನು ಬದಲಿಸುವುದಿಲ್ಲ. ನಿಮ್ಮ ಪರಿಸ್ಥಿತಿಗೆ ನಿರ್ದಿಷ್ಟವಾದ ಕಾನೂನು ಸಲಹೆಗಾಗಿ, ನಿಮ್ಮ ಅಧಿಕಾರ ವ್ಯಾಪ್ತಿಯಲ್ಲಿ ಅರ್ಹ ವಕೀಲರನ್ನು ಸಂಪರ್ಕಿಸಿ. AI- ರಚಿತವಾದ ವಿಷಯವನ್ನು ಮಾಹಿತಿ ಉದ್ದೇಶಗಳಿಗಾಗಿ ಮಾತ್ರ ಒದಗಿಸಲಾಗಿದೆ ಮತ್ತು ಕಾನೂನು ಸಲಹೆ, ಕಾನೂನು ಪ್ರಾತಿನಿಧ್ಯ ಅಥವಾ ನಿಮ್ಮ ಮತ್ತು DVTech ವೆಂಚರ್ಸ್ ನಡುವೆ ವಕೀಲ-ಕ್ಲೈಂಟ್ ಸಂಬಂಧದ ರಚನೆಯನ್ನು ರೂಪಿಸುವುದಿಲ್ಲ.';

  @override
  String get legalDisclaimerUniversalHeading => 'ಸಾರ್ವತ್ರಿಕ ಹಕ್ಕು ನಿರಾಕರಣೆ';

  @override
  String get legalDisclaimerUserResponsibilitiesBody =>
      'ವೇದಿಕೆಯನ್ನು ಬಳಸುವ ಮೂಲಕ ನೀವು ಜವಾಬ್ದಾರಿಯನ್ನು ಸ್ವೀಕರಿಸುತ್ತೀರಿ: (a) ನಿಮ್ಮ ನಿರ್ದಿಷ್ಟ ಸನ್ನಿವೇಶಕ್ಕೆ AI ಔಟ್‌ಪುಟ್‌ಗಳ ನಿಖರತೆ ಮತ್ತು ಅನ್ವಯಿಸುವಿಕೆಯನ್ನು ಮೌಲ್ಯಮಾಪನ ಮಾಡುವುದು; (ಬಿ) ಸೂಕ್ತವಾದಲ್ಲಿ ಸ್ವತಂತ್ರ ಕಾನೂನು ಸಲಹೆಯನ್ನು ಪಡೆಯುವುದು; (ಸಿ) AI ಔಟ್‌ಪುಟ್‌ಗಳ ನಿಮ್ಮ ಬಳಕೆಯು ನಿಮ್ಮ ವೃತ್ತಿಪರ ಕಟ್ಟುಪಾಡುಗಳಿಗೆ (ವಕೀಲ ಬಳಕೆದಾರರು) ಅನುಸರಿಸುತ್ತದೆ ಎಂದು ಖಚಿತಪಡಿಸಿಕೊಳ್ಳುವುದು; (ಡಿ) ಅನುಮತಿಯಿಲ್ಲದೆ ಮೂರನೇ ವ್ಯಕ್ತಿಯ ಗೌಪ್ಯ ಮಾಹಿತಿಯನ್ನು ಸಲ್ಲಿಸದಿರುವುದು; (ಇ) ನಿಮ್ಮ ಖಾತೆಯ ರುಜುವಾತುಗಳನ್ನು ಸುರಕ್ಷಿತವಾಗಿರಿಸುವುದು.';

