  @override
  String get legalPrivacyAutomatedBody =>
      'ಅಂಬ್ರೆಲಾ ಕಾನೂನು ವಿಶ್ಲೇಷಣೆಯನ್ನು ರಚಿಸಲು, ಸಮಸ್ಯೆಗಳನ್ನು ಗುರುತಿಸಲು ಮತ್ತು ಕ್ರಮಗಳನ್ನು ಸೂಚಿಸಲು AI ಅನ್ನು ಬಳಸುತ್ತದೆ. ಈ AI ಔಟ್‌ಪುಟ್‌ಗಳು ಕೇವಲ ಮಾಹಿತಿಯುಕ್ತವಾಗಿವೆ ಮತ್ತು ನಿಮ್ಮ ಕಾನೂನು ಹಕ್ಕುಗಳ ಬಗ್ಗೆ ಬಂಧಿಸುವ ನಿರ್ಧಾರಗಳನ್ನು ರೂಪಿಸುವುದಿಲ್ಲ. ಮಾನವ ವಿಮರ್ಶೆಯಿಲ್ಲದೆ ನಿಮ್ಮ ಬಗ್ಗೆ ಕಾನೂನು ಅಥವಾ ಅದೇ ರೀತಿಯ ಮಹತ್ವದ ಪರಿಣಾಮದೊಂದಿಗೆ ಯಾವುದೇ ಸಂಪೂರ್ಣ ಸ್ವಯಂಚಾಲಿತ ನಿರ್ಧಾರವನ್ನು ತೆಗೆದುಕೊಳ್ಳಲಾಗುವುದಿಲ್ಲ. ವಂಚನೆ ಪತ್ತೆಗಾಗಿ ನಮ್ಮ AI ಅಪಾಯ-ಸ್ಕೋರಿಂಗ್ ಪ್ಲಾಟ್‌ಫಾರ್ಮ್ ಪ್ರವೇಶದ ಮೇಲೆ ಪರಿಣಾಮ ಬೀರಬಹುದು; ಅಂತಹ ಯಾವುದೇ ನಿರ್ಧಾರವನ್ನು ನೀವು ಮಾನವ ವಿಮರ್ಶೆಗೆ ವಿನಂತಿಸಬಹುದು.';

  @override
  String get legalPrivacyAutomatedHeading => '11. ಸ್ವಯಂಚಾಲಿತ ನಿರ್ಧಾರ-ಮಾಡುವಿಕೆ';

  @override
  String get legalPrivacyChangesBody =>
      'ನಾವು ಈ ಗೌಪ್ಯತಾ ನೀತಿಯನ್ನು ಕಾಲಕಾಲಕ್ಕೆ ನವೀಕರಿಸಬಹುದು. ವಸ್ತು ಬದಲಾವಣೆಗಳನ್ನು ಇಮೇಲ್ ಮತ್ತು ಅಪ್ಲಿಕೇಶನ್‌ನಲ್ಲಿನ ಅಧಿಸೂಚನೆಯ ಮೂಲಕ ಅವು ಪರಿಣಾಮ ಬೀರುವ ಕನಿಷ್ಠ 30 ದಿನಗಳ ಮೊದಲು ತಿಳಿಸಲಾಗುತ್ತದೆ. ಪರಿಣಾಮಕಾರಿ ದಿನಾಂಕದ ನಂತರ ಪ್ಲಾಟ್‌ಫಾರ್ಮ್‌ನ ಮುಂದುವರಿದ ಬಳಕೆಯು ನವೀಕರಿಸಿದ ನೀತಿಯನ್ನು ಅಂಗೀಕರಿಸುತ್ತದೆ.';

