  @override
  String get legalPrivacyChildrenBody =>
      '18 ವರ್ಷಕ್ಕಿಂತ ಕಡಿಮೆ ವಯಸ್ಸಿನ ವ್ಯಕ್ತಿಗಳಿಗೆ ಅಂಬ್ರೆಲಾವನ್ನು ನಿರ್ದೇಶಿಸಲಾಗುವುದಿಲ್ಲ. ನಾವು ಉದ್ದೇಶಪೂರ್ವಕವಾಗಿ ಮಕ್ಕಳಿಂದ ವೈಯಕ್ತಿಕ ಡೇಟಾವನ್ನು ಸಂಗ್ರಹಿಸುವುದಿಲ್ಲ. ಮಗುವು ನಮಗೆ ಡೇಟಾವನ್ನು ಸಲ್ಲಿಸಿದೆ ಎಂದು ನೀವು ಭಾವಿಸಿದರೆ, support@odaflow.com ಅನ್ನು ಸಂಪರ್ಕಿಸಿ ಮತ್ತು ನಾವು ಅದನ್ನು ತ್ವರಿತವಾಗಿ ಅಳಿಸುತ್ತೇವೆ.';

  @override
