  @override
  String get legalPrivacyCollectBillingBody =>
      'ಬಿಲ್ಲಿಂಗ್ ಡೇಟಾ: ಚಂದಾದಾರಿಕೆ ಯೋಜನೆ, ಪಾವತಿ ವಿಧಾನದ ಪ್ರಕಾರ (ಕಾರ್ಡ್ ಬ್ರ್ಯಾಂಡ್, ಕೊನೆಯ ನಾಲ್ಕು ಅಂಕೆಗಳು), ಬಿಲ್ಲಿಂಗ್ ವಿಳಾಸ ಮತ್ತು ವಹಿವಾಟಿನ ಇತಿಹಾಸ. ಪೂರ್ಣ ಪಾವತಿ ಕಾರ್ಡ್ ವಿವರಗಳನ್ನು ನಮ್ಮ ಪಿಸಿಐ-ಡಿಎಸ್ಎಸ್-ಕಂಪ್ಲೈಂಟ್ ಪಾವತಿ ಪ್ರೊಸೆಸರ್ (ಸ್ಟ್ರೈಪ್) ನಿರ್ವಹಿಸುತ್ತದೆ ಮತ್ತು ನಮ್ಮ ಸರ್ವರ್‌ಗಳಲ್ಲಿ ಎಂದಿಗೂ ಸಂಗ್ರಹಿಸಲಾಗುವುದಿಲ್ಲ.';

  @override
  String get legalPrivacyCollectContentBody =>
