  @override
  String get legalPrivacyCollectCookiesBody =>
      'ಕುಕೀಸ್ ಮತ್ತು ಟ್ರ್ಯಾಕಿಂಗ್: ನಾವು ಕಟ್ಟುನಿಟ್ಟಾಗಿ-ಅಗತ್ಯವಿರುವ ಸೆಷನ್ ಕುಕೀಸ್, ಕ್ರಿಯಾತ್ಮಕ ಆದ್ಯತೆಯ ಕುಕೀಗಳನ್ನು ಬಳಸುತ್ತೇವೆ ಮತ್ತು — ನಿಮ್ಮ ಒಪ್ಪಿಗೆಯೊಂದಿಗೆ — ವಿಶ್ಲೇಷಣಾ ಕುಕೀಗಳನ್ನು (ವರ್ಸೆಲ್ ಅನಾಲಿಟಿಕ್ಸ್, ಸೆಂಟ್ರಿ ದೋಷ ಟ್ರ್ಯಾಕಿಂಗ್) ಬಳಸುತ್ತೇವೆ. ಕುಕೀ ಸೆಟ್ಟಿಂಗ್‌ಗಳ ಫಲಕದ ಮೂಲಕ ನೀವು ಕುಕೀ ಆದ್ಯತೆಗಳನ್ನು ನಿರ್ವಹಿಸಬಹುದು.';

  @override
  String get legalPrivacyCollectDeviceBody =>
      'ಸಾಧನ ಮತ್ತು ತಾಂತ್ರಿಕ ಡೇಟಾ: IP ವಿಳಾಸ, ಬ್ರೌಸರ್ ಪ್ರಕಾರ, ಆಪರೇಟಿಂಗ್ ಸಿಸ್ಟಮ್, ಸಾಧನ ಗುರುತಿಸುವಿಕೆಗಳು, ಪರದೆಯ ರೆಸಲ್ಯೂಶನ್ ಮತ್ತು ಸಮಯ ವಲಯ. ಭದ್ರತೆ, ವಂಚನೆ ತಡೆಗಟ್ಟುವಿಕೆ ಮತ್ತು ಸೇವಾ ಹೊಂದಾಣಿಕೆಗಾಗಿ ಬಳಸಲಾಗುತ್ತದೆ.';

  @override
  String get legalPrivacyCollectHeading => 'ನಾವು ಸಂಗ್ರಹಿಸುವ ಮಾಹಿತಿ';

  @override
  String get legalPrivacyCollectUsageBody =>
      'ಬಳಕೆಯ ಡೇಟಾ: ಭೇಟಿ ನೀಡಿದ ಪುಟಗಳು, ಬಳಸಿದ ವೈಶಿಷ್ಟ್ಯಗಳು, ಸಲ್ಲಿಸಿದ AI ಪ್ರಶ್ನೆಗಳು, ಅಪ್‌ಲೋಡ್ ಮಾಡಿದ ದಾಖಲೆಗಳು, ಕಳೆದ ಸಮಯ, ಈವೆಂಟ್‌ಗಳನ್ನು ಕ್ಲಿಕ್ ಮಾಡಿ ಮತ್ತು ಸೆಷನ್ ರೆಕಾರ್ಡಿಂಗ್‌ಗಳು (ಸಮ್ಮತಿಯನ್ನು ನೀಡಿದರೆ). ಈ ಡೇಟಾವನ್ನು ಫಸ್ಟ್-ಪಾರ್ಟಿ ಅನಾಲಿಟಿಕ್ಸ್ ಮೂಲಕ ಸಂಗ್ರಹಿಸಲಾಗಿದೆ.';

  @override
  String get legalPrivacyContactBody =>
      'ಡೇಟಾ ರಕ್ಷಣೆ ವಿಚಾರಣೆಗಳು: support@odaflow.com. ನಾವು 10 ವ್ಯವಹಾರ ದಿನಗಳಲ್ಲಿ ಪ್ರತಿಕ್ರಿಯಿಸುವ ಗುರಿಯನ್ನು ಹೊಂದಿದ್ದೇವೆ. ನಮ್ಮ ಪ್ರತಿಕ್ರಿಯೆಯಿಂದ ನೀವು ಅತೃಪ್ತರಾಗಿದ್ದರೆ ನಿಮ್ಮ ಸ್ಥಳೀಯ ಡೇಟಾ ಸಂರಕ್ಷಣಾ ಪ್ರಾಧಿಕಾರದೊಂದಿಗೆ ದೂರು ಸಲ್ಲಿಸಲು ನೀವು ಹಕ್ಕನ್ನು ಹೊಂದಿದ್ದೀರಿ: UK — ICO (ico.org.uk); EU - ನಿಮ್ಮ ರಾಷ್ಟ್ರೀಯ DPA; ಭಾರತ - ಭಾರತದ ಡೇಟಾ ಸಂರಕ್ಷಣಾ ಮಂಡಳಿ; ಕೀನ್ಯಾ — ಡಾಟಾ ಪ್ರೊಟೆಕ್ಷನ್ ಕಮಿಷನರ್ ಕಚೇರಿ (odpc.go.ke).';

  @override
  String get legalPrivacyContactHeading => '14. ನಮ್ಮನ್ನು ಸಂಪರ್ಕಿಸಿ';

  @override
  String get legalPrivacyControllerBody =>
      'ಅಂಬ್ರೆಲಾವನ್ನು DVTech ವೆಂಚರ್ಸ್ ನಿರ್ವಹಿಸುತ್ತದೆ (\"ನಾವು\", \"ನಮಗೆ\", \"ನಮ್ಮ\"). ಗ್ರಾಹಕರಿಂದ ಸಂಗ್ರಹಿಸಿದ ಮಾಹಿತಿಗಾಗಿ ನಾವು ಡೇಟಾ ನಿಯಂತ್ರಕರಾಗಿ ಮತ್ತು ಕಾನೂನು ಸಂಸ್ಥೆಯ ಬಾಡಿಗೆದಾರರ ಪರವಾಗಿ ಮಾಹಿತಿಗಾಗಿ ಡೇಟಾ ಪ್ರೊಸೆಸರ್ ಆಗಿ ಕಾರ್ಯನಿರ್ವಹಿಸುತ್ತೇವೆ. ನೋಂದಾಯಿತ ವಿಳಾಸ ಮತ್ತು ಡೇಟಾ ರಕ್ಷಣೆ ಸಂಪರ್ಕ: support@odaflow.com. GDPR ಉದ್ದೇಶಗಳಿಗಾಗಿ, ನಮ್ಮ EU/UK ಪ್ರತಿನಿಧಿಯನ್ನು ಅದೇ ವಿಳಾಸದಲ್ಲಿ ಸಂಪರ್ಕಿಸಬಹುದು.';

  @override
  String get legalPrivacyControllerHeading => '1. ನಾವು ಯಾರು';

  @override
  String get legalPrivacyCookiesBody =>
      'ಕಟ್ಟುನಿಟ್ಟಾಗಿ ಅಗತ್ಯವಿರುವ ಕುಕೀಗಳು (ಸೆಷನ್ ನಿರ್ವಹಣೆ, ಭದ್ರತಾ ಟೋಕನ್‌ಗಳು) ಯಾವಾಗಲೂ ಸಕ್ರಿಯವಾಗಿರುತ್ತವೆ. ಕ್ರಿಯಾತ್ಮಕ ಕುಕೀಗಳನ್ನು (ಭಾಷೆಯ ಆದ್ಯತೆ, ಥೀಮ್) ಮೊದಲ ಬಳಕೆಯಲ್ಲಿ ಹೊಂದಿಸಲಾಗಿದೆ ಮತ್ತು ಬ್ರೌಸರ್ ಸೆಟ್ಟಿಂಗ್‌ಗಳಲ್ಲಿ ತೆರವುಗೊಳಿಸಬಹುದು. ಅನಾಲಿಟಿಕ್ಸ್ ಕುಕೀಗಳನ್ನು (ವರ್ಸೆಲ್, ಸೆಂಟ್ರಿ) ಕುಕೀ ಬ್ಯಾನರ್ ಮೂಲಕ ನಿಮ್ಮ ಒಪ್ಪಿಗೆಯೊಂದಿಗೆ ಮಾತ್ರ ಹೊಂದಿಸಲಾಗಿದೆ. ನಾವು ಜಾಹೀರಾತು ಅಥವಾ ಕ್ರಾಸ್-ಸೈಟ್ ಟ್ರ್ಯಾಕಿಂಗ್ ಕುಕೀಗಳನ್ನು ಬಳಸುವುದಿಲ್ಲ.';

  @override
  String get legalPrivacyCookiesHeading => '12. ಕುಕೀಸ್';

  @override
  String get legalPrivacyDescription =>
      'ಅಂಬ್ರೆಲಾ ನಿಮ್ಮ ಮಾಹಿತಿಯನ್ನು ಹೇಗೆ ಸಂಗ್ರಹಿಸುತ್ತದೆ, ಬಳಸುತ್ತದೆ ಮತ್ತು ರಕ್ಷಿಸುತ್ತದೆ.';

  @override
  String get legalPrivacyLegalBasisBody =>
      'ನಿಮ್ಮ ಅಧಿಕಾರ ವ್ಯಾಪ್ತಿಗೆ ಅನುಗುಣವಾಗಿ ನಾವು ಕೆಳಗಿನ ಕಾನೂನು ಆಧಾರಗಳ ಅಡಿಯಲ್ಲಿ ವೈಯಕ್ತಿಕ ಡೇಟಾವನ್ನು ಪ್ರಕ್ರಿಯೆಗೊಳಿಸುತ್ತೇವೆ: (ಎ) ಒಪ್ಪಂದ - ನೀವು ಸೈನ್ ಅಪ್ ಮಾಡಿದ ಸೇವೆಗಳನ್ನು ತಲುಪಿಸಲು ಅಗತ್ಯವಾದ ಪ್ರಕ್ರಿಯೆ; (ಬಿ) ಕಾನೂನುಬದ್ಧ ಆಸಕ್ತಿಗಳು - ವಂಚನೆ ತಡೆಗಟ್ಟುವಿಕೆ, ವೇದಿಕೆ ಭದ್ರತೆ, ಉತ್ಪನ್ನ ಸುಧಾರಣೆ; (ಸಿ) ಸಮ್ಮತಿ - AI ತರಬೇತಿ, ಮಾರ್ಕೆಟಿಂಗ್ ಇಮೇಲ್‌ಗಳು, ಕಟ್ಟುನಿಟ್ಟಾಗಿ ಅಗತ್ಯಕ್ಕಿಂತ ಕುಕೀಗಳು; (ಡಿ) ಕಾನೂನು ಬಾಧ್ಯತೆ - ಅನ್ವಯವಾಗುವ ಕಾನೂನಿನ ಅನುಸರಣೆ. ಭಾರತಕ್ಕೆ ಸಂಬಂಧಿಸಿದಂತೆ, ಪ್ರಕ್ರಿಯೆಯು ಡಿಜಿಟಲ್ ವೈಯಕ್ತಿಕ ಡೇಟಾ ಸಂರಕ್ಷಣಾ ಕಾಯಿದೆ 2023 (DPDP ಕಾಯಿದೆ) ಯಿಂದ ನಿಯಂತ್ರಿಸಲ್ಪಡುತ್ತದೆ. UK/EU ಗಾಗಿ, ಪ್ರಕ್ರಿಯೆಯು UK GDPR ಮತ್ತು EU GDPR ಅನ್ನು ಅನುಸರಿಸುತ್ತದೆ. ಕೀನ್ಯಾಕ್ಕೆ ಸಂಬಂಧಿಸಿದಂತೆ, ಪ್ರಕ್ರಿಯೆಯು ಡೇಟಾ ಸಂರಕ್ಷಣಾ ಕಾಯಿದೆ 2019 ಕ್ಕೆ ಅನುಗುಣವಾಗಿರುತ್ತದೆ. US ಬಳಕೆದಾರರಿಗೆ, ನಾವು CCPA/CPRA ಸೇರಿದಂತೆ ಅನ್ವಯವಾಗುವ ರಾಜ್ಯದ ಗೌಪ್ಯತೆ ಕಾನೂನುಗಳನ್ನು ಅನುಸರಿಸುತ್ತೇವೆ.';

  @override
  String get legalPrivacyLegalBasisHeading => '2. ಪ್ರಕ್ರಿಯೆಗೆ ಕಾನೂನು ಆಧಾರಗಳು';

  @override
  String get legalPrivacyPolicy => 'ಗೌಪ್ಯತೆ ನೀತಿ';

  @override
  String get legalPrivacyRetentionBody =>
      'ಡೇಟಾವನ್ನು ಸಾಗಣೆಯಲ್ಲಿ ಮತ್ತು ವಿಶ್ರಾಂತಿಯಲ್ಲಿ ಎನ್‌ಕ್ರಿಪ್ಟ್ ಮಾಡಲಾಗಿದೆ. ಧಾರಣವು ನಿಮ್ಮ ಸಂಸ್ಥೆಯ ಆಡಳಿತ ಸೆಟ್ಟಿಂಗ್‌ಗಳು ಅಥವಾ ಗ್ರಾಹಕರ ಖಾತೆ ಅಳಿಸುವಿಕೆ ವಿನಂತಿಗಳನ್ನು ಅನುಸರಿಸುತ್ತದೆ, ಕಾನೂನು ಹಿಡಿತದ ಅವಶ್ಯಕತೆಗಳಿಗೆ ಒಳಪಟ್ಟಿರುತ್ತದೆ.';

  @override
  String get legalPrivacyRetentionHeading => 'ಧಾರಣ ಮತ್ತು ಭದ್ರತೆ';

  @override
  String get legalPrivacyRightsCCPABody =>
      'ಕ್ಯಾಲಿಫೋರ್ನಿಯಾ (CCPA/CPRA) ಹಕ್ಕುಗಳು: ನಾವು ಯಾವ ವೈಯಕ್ತಿಕ ಮಾಹಿತಿಯನ್ನು ಸಂಗ್ರಹಿಸುತ್ತೇವೆ ಎಂಬುದನ್ನು ತಿಳಿದುಕೊಳ್ಳುವ ಹಕ್ಕು; ಅಳಿಸುವ ಹಕ್ಕು; ಮಾರಾಟದಿಂದ ಹೊರಗುಳಿಯುವ ಹಕ್ಕು (ನಾವು ಡೇಟಾವನ್ನು ಮಾರಾಟ ಮಾಡುವುದಿಲ್ಲ); ಹಕ್ಕುಗಳನ್ನು ಚಲಾಯಿಸಲು ತಾರತಮ್ಯದ ಹಕ್ಕು; ತಪ್ಪಾದ ಮಾಹಿತಿಯನ್ನು ಸರಿಪಡಿಸುವ ಹಕ್ಕು; ಸೂಕ್ಷ್ಮ ವೈಯಕ್ತಿಕ ಮಾಹಿತಿಯ ಬಳಕೆಯನ್ನು ಮಿತಿಗೊಳಿಸುವ ಹಕ್ಕು.';

  @override
  String get legalPrivacyRightsDPDPBody =>
      'ಭಾರತದ DPDP ಕಾಯಿದೆಯ ಹಕ್ಕುಗಳು: ನಿಮ್ಮ ಡಿಜಿಟಲ್ ವೈಯಕ್ತಿಕ ಡೇಟಾವನ್ನು ಪ್ರವೇಶಿಸುವ, ತಿದ್ದುಪಡಿ ಮಾಡುವ ಮತ್ತು ಅಳಿಸುವ ಹಕ್ಕು; ಕುಂದುಕೊರತೆ ಪರಿಹಾರದ ಹಕ್ಕು; ನಿಮ್ಮ ಪರವಾಗಿ ಹಕ್ಕುಗಳನ್ನು ಚಲಾಯಿಸಲು ವ್ಯಕ್ತಿಯನ್ನು ನಾಮನಿರ್ದೇಶನ ಮಾಡುವ ಹಕ್ಕು. support@odaflow.com ನಲ್ಲಿ ನಮ್ಮ ಸಮ್ಮತಿ ನಿರ್ವಾಹಕರನ್ನು ಸಂಪರ್ಕಿಸಿ.';

  @override
  String get legalPrivacyRightsGDPRBody =>
      'GDPR / UK GDPR ಹಕ್ಕುಗಳು (EU ಮತ್ತು UK ಬಳಕೆದಾರರು): ಪ್ರವೇಶ - ನಿಮ್ಮ ವೈಯಕ್ತಿಕ ಡೇಟಾದ ನಕಲನ್ನು ಪಡೆದುಕೊಳ್ಳಿ; ಸರಿಪಡಿಸುವಿಕೆ - ಸರಿಯಾದ ನಿಖರವಾದ ಡೇಟಾ; ಅಳಿಸುವಿಕೆ - ವಿನಂತಿ ಅಳಿಸುವಿಕೆ (ಕಾನೂನು ಹಿಡಿತಕ್ಕೆ ಒಳಪಟ್ಟಿರುತ್ತದೆ); ನಿರ್ಬಂಧ - ವಿವಾದವನ್ನು ಪರಿಹರಿಸುವಾಗ ಮಿತಿ ಪ್ರಕ್ರಿಯೆ; ಪೋರ್ಟಬಿಲಿಟಿ - ನಿಮ್ಮ ಡೇಟಾವನ್ನು ಯಂತ್ರ-ಓದಬಲ್ಲ ಸ್ವರೂಪದಲ್ಲಿ ಸ್ವೀಕರಿಸಿ; ಆಕ್ಷೇಪಣೆ - ಕಾನೂನುಬದ್ಧ ಆಸಕ್ತಿಗಳ ಆಧಾರದ ಮೇಲೆ ಪ್ರಕ್ರಿಯೆಗೆ ವಸ್ತು; ಸ್ವಯಂಚಾಲಿತ ನಿರ್ಧಾರಗಳು - ಗಮನಾರ್ಹ ಪರಿಣಾಮಗಳೊಂದಿಗೆ ಕೇವಲ ಸ್ವಯಂಚಾಲಿತ ನಿರ್ಧಾರಗಳಿಗೆ ಒಳಪಟ್ಟಿರಬಾರದು. ಈ ಹಕ್ಕುಗಳನ್ನು ಚಲಾಯಿಸಲು, support@odaflow.com ಗೆ ಇಮೇಲ್ ಮಾಡಿ ಅಥವಾ ಅಪ್ಲಿಕೇಶನ್‌ನಲ್ಲಿನ ಗೌಪ್ಯತೆ ಸೆಟ್ಟಿಂಗ್‌ಗಳನ್ನು ಬಳಸಿ.';

