  @override
  String get legalPrivacySecurityBody =>
      'ನಾವು ತಾಂತ್ರಿಕ ಮತ್ತು ಸಾಂಸ್ಥಿಕ ಕ್ರಮಗಳನ್ನು ಅಳವಡಿಸಿಕೊಳ್ಳುತ್ತೇವೆ: TLS 1.2+ ಸಾರಿಗೆಯಲ್ಲಿ ಎನ್‌ಕ್ರಿಪ್ಶನ್; ವಿಶ್ರಾಂತಿಯಲ್ಲಿ AES-256 ಗೂಢಲಿಪೀಕರಣ; ಕನಿಷ್ಠ-ಸವಲತ್ತು ತತ್ವಗಳೊಂದಿಗೆ ಪಾತ್ರ-ಆಧಾರಿತ ಪ್ರವೇಶ ನಿಯಂತ್ರಣ; ಆಡಳಿತಾತ್ಮಕ ಪ್ರವೇಶಕ್ಕಾಗಿ ಬಹು ಅಂಶದ ದೃಢೀಕರಣ; ಸ್ವಯಂಚಾಲಿತ ದುರ್ಬಲತೆ ಸ್ಕ್ಯಾನಿಂಗ್; ಕನಿಷ್ಠ ವಾರ್ಷಿಕವಾಗಿ ನುಗ್ಗುವ ಪರೀಕ್ಷೆ; ಮತ್ತು ಘಟನೆ ಪ್ರತಿಕ್ರಿಯೆ ಯೋಜನೆ. ನಿಮ್ಮ ಹಕ್ಕುಗಳ ಮೇಲೆ ಪರಿಣಾಮ ಬೀರುವ ವೈಯಕ್ತಿಕ ಡೇಟಾ ಉಲ್ಲಂಘನೆಯ ಸಂದರ್ಭದಲ್ಲಿ, ಅನ್ವಯವಾಗುವ ಕಾನೂನಿನ ಅಡಿಯಲ್ಲಿ ಅಗತ್ಯವಿರುವಂತೆ, ಅರಿವು ಮೂಡಿಸಿದ 72 ಗಂಟೆಗಳ ಒಳಗೆ ನಾವು ನಿಮಗೆ ಸೂಚಿಸುತ್ತೇವೆ.';

