  @override
  String get legalStandardDisclaimer =>
      'ಅಂಬ್ರೆಲಾ ಕಾನೂನು ಮಾಹಿತಿ, ದಾಖಲೆ ವಿವರಣೆಗಳು, ಸಮಸ್ಯೆ ಗುರುತಿಸುವಿಕೆ ಮತ್ತು ಅಪಾಯದ ವಿಶ್ಲೇಷಣೆಯನ್ನು ಒದಗಿಸುತ್ತದೆ. ಇದು ಕಾನೂನು ಸಂಸ್ಥೆಯಲ್ಲ ಮತ್ತು ಪರವಾನಗಿ ಪಡೆದ ವಕೀಲರನ್ನು ಬದಲಿಸುವುದಿಲ್ಲ. ನಿಮ್ಮ ಪರಿಸ್ಥಿತಿಗೆ ನಿರ್ದಿಷ್ಟವಾದ ಕಾನೂನು ಸಲಹೆಗಾಗಿ, ನಿಮ್ಮ ಅಧಿಕಾರ ವ್ಯಾಪ್ತಿಯಲ್ಲಿ ಅರ್ಹ ವಕೀಲರನ್ನು ಸಂಪರ್ಕಿಸಿ.';

  @override
  String get legalTermsAIOutputsBody =>
      'AI ಔಟ್‌ಪುಟ್‌ಗಳನ್ನು ದೊಡ್ಡ ಭಾಷಾ ಮಾದರಿಗಳಿಂದ ರಚಿಸಲಾಗಿದೆ ಮತ್ತು ಮಾಹಿತಿ ಉದ್ದೇಶಗಳಿಗಾಗಿ ಮಾತ್ರ ಒದಗಿಸಲಾಗಿದೆ. ಅವರು ಕಾನೂನು ಸಲಹೆಯನ್ನು ಹೊಂದಿರುವುದಿಲ್ಲ, ವಕೀಲ-ಕ್ಲೈಂಟ್ ಸಂಬಂಧವನ್ನು ರಚಿಸುವುದಿಲ್ಲ ಮತ್ತು ಅರ್ಹ ವಕೀಲರ ಸಲಹೆಗಾಗಿ ಬದಲಿಯಾಗಿ ಅವಲಂಬಿಸಬಾರದು. AI ಔಟ್‌ಪುಟ್‌ಗಳು ಅಪೂರ್ಣವಾಗಿರಬಹುದು, ತಪ್ಪಾಗಿರಬಹುದು ಅಥವಾ ಹಳೆಯದಾಗಿರಬಹುದು. ಕಾನೂನುಗಳು ಮತ್ತು ಪ್ರಕರಣಗಳ ಉಲ್ಲೇಖಗಳನ್ನು ಸ್ವತಂತ್ರವಾಗಿ ಪರಿಶೀಲಿಸಬೇಕು. AI ಔಟ್‌ಪುಟ್‌ಗಳ ಆಧಾರದ ಮೇಲೆ ತೆಗೆದುಕೊಂಡ ಯಾವುದೇ ಕ್ರಮಕ್ಕೆ ನೀವು ಮಾತ್ರ ಜವಾಬ್ದಾರರಾಗಿರುತ್ತೀರಿ.';

  @override
  String get legalTermsAIOutputsHeading => '9. AI ಔಟ್‌ಪುಟ್‌ಗಳ ಸ್ವರೂಪ';

  @override
  String get legalTermsAccountBody =>
      'ನೀವು ನಿಖರವಾದ ಮತ್ತು ಸಂಪೂರ್ಣ ನೋಂದಣಿ ಮಾಹಿತಿಯನ್ನು ಒದಗಿಸಬೇಕು ಮತ್ತು ಅದನ್ನು ನವೀಕರಿಸಬೇಕು. ನಿಮ್ಮ ರುಜುವಾತುಗಳ ಗೌಪ್ಯತೆಯನ್ನು ಕಾಪಾಡಿಕೊಳ್ಳಲು ಮತ್ತು ನಿಮ್ಮ ಖಾತೆಯ ಅಡಿಯಲ್ಲಿ ಎಲ್ಲಾ ಚಟುವಟಿಕೆಗಳಿಗೆ ನೀವು ಜವಾಬ್ದಾರರಾಗಿರುತ್ತೀರಿ. support@odaflow.com ನಲ್ಲಿ ಯಾವುದೇ ಅನಧಿಕೃತ ಪ್ರವೇಶದ ಕುರಿತು ನೀವು ತಕ್ಷಣ ನಮಗೆ ಸೂಚಿಸಬೇಕು. ಈ ನಿಯಮಗಳನ್ನು ಉಲ್ಲಂಘಿಸುವ ಖಾತೆಗಳನ್ನು ನಿಷ್ಕ್ರಿಯಗೊಳಿಸುವ ಹಕ್ಕನ್ನು ನಾವು ಕಾಯ್ದಿರಿಸಿದ್ದೇವೆ ಅಥವಾ ರಾಜಿ ಮಾಡಿಕೊಂಡಿದ್ದೇವೆ ಎಂದು ನಾವು ಸಮಂಜಸವಾಗಿ ಅನುಮಾನಿಸುತ್ತೇವೆ.';

  @override
  String get legalTermsAccountHeading => '3. ಖಾತೆ ನೋಂದಣಿ';

  @override
  String get legalTermsAgreementBody =>
      'ಅಂಬ್ರೆಲಾವನ್ನು ಪ್ರವೇಶಿಸುವ ಮೂಲಕ, ನೀವು ಈ ನಿಯಮಗಳನ್ನು ಒಪ್ಪುತ್ತೀರಿ. ನೀವು ಕಾನೂನು ಸಂಸ್ಥೆಯ ಪರವಾಗಿ ವೇದಿಕೆಯನ್ನು ಬಳಸಿದರೆ, ಆ ಸಂಸ್ಥೆಯನ್ನು ಬಂಧಿಸಲು ನಿಮಗೆ ಅಧಿಕಾರವಿದೆ ಎಂದು ನೀವು ಪ್ರತಿನಿಧಿಸುತ್ತೀರಿ.';

  @override
  String get legalTermsAgreementHeading => '1. ಒಪ್ಪಂದ';

  @override
  String get legalTermsChangesBody =>
      'ನಾವು ಈ ನಿಯಮಗಳನ್ನು ಕಾಲಕಾಲಕ್ಕೆ ನವೀಕರಿಸಬಹುದು. ವಸ್ತು ಬದಲಾವಣೆಗಳನ್ನು ಇಮೇಲ್ ಮತ್ತು ಅಪ್ಲಿಕೇಶನ್‌ನಲ್ಲಿನ ಅಧಿಸೂಚನೆಯ ಮೂಲಕ ಅವು ಪರಿಣಾಮ ಬೀರುವ ಕನಿಷ್ಠ 30 ದಿನಗಳ ಮೊದಲು ತಿಳಿಸಲಾಗುತ್ತದೆ. ಪರಿಣಾಮಕಾರಿ ದಿನಾಂಕದ ನಂತರ ಮುಂದುವರಿದ ಬಳಕೆಯು ಸ್ವೀಕಾರವನ್ನು ರೂಪಿಸುತ್ತದೆ.';

  @override
  String get legalTermsChangesHeading => '20. ಈ ನಿಯಮಗಳಿಗೆ ಬದಲಾವಣೆಗಳು';

  @override
  String get legalTermsConfidentialityBody =>
      'ನಿಮ್ಮ ವಿಷಯ ಮತ್ತು ವಿಷಯದ ಡೇಟಾವನ್ನು ನಾವು ಗೌಪ್ಯವಾಗಿ ಪರಿಗಣಿಸುತ್ತೇವೆ ಮತ್ತು ನಮ್ಮ ಗೌಪ್ಯತೆ ನೀತಿಯಲ್ಲಿ ವಿವರಿಸಿದಂತೆ ಅಥವಾ ಕಾನೂನಿನ ಪ್ರಕಾರ ಹೊರತುಪಡಿಸಿ ಅದನ್ನು ಮೂರನೇ ವ್ಯಕ್ತಿಗಳಿಗೆ ಬಹಿರಂಗಪಡಿಸುವುದಿಲ್ಲ. ವಕೀಲ ಬಳಕೆದಾರರು ಕ್ಲೈಂಟ್-ಗೌಪ್ಯ ಸಂವಹನಗಳು ಅನ್ವಯವಾಗುವ ವೃತ್ತಿಪರ ಸವಲತ್ತು ನಿಯಮಗಳಿಗೆ ಅನುಗುಣವಾಗಿರುವುದನ್ನು ಖಚಿತಪಡಿಸಿಕೊಳ್ಳಬೇಕು. ಬಾಡಿಗೆದಾರರ ಡೇಟಾವನ್ನು ಪ್ರತ್ಯೇಕಿಸಲು ನಮ್ಮ ಸಿಸ್ಟಂಗಳನ್ನು ವಿನ್ಯಾಸಗೊಳಿಸಲಾಗಿದೆ.';

  @override
  String get legalTermsConfidentialityHeading => '13. ಗೌಪ್ಯತೆ';

  @override
  String get legalTermsContactBody =>
      'ಈ ನಿಯಮಗಳ ಕುರಿತು ಪ್ರಶ್ನೆಗಳು: support@odaflow.com';

  @override
  String get legalTermsContactHeading => '7. ಸಂಪರ್ಕಿಸಿ';

  @override
  String get legalTermsDataBody =>
      'ನಮ್ಮ ವೈಯಕ್ತಿಕ ಡೇಟಾದ ಸಂಗ್ರಹಣೆ ಮತ್ತು ಬಳಕೆಯನ್ನು ಗೌಪ್ಯತೆ ನೀತಿಯಲ್ಲಿ ವಿವರಿಸಲಾಗಿದೆ. ಡೇಟಾ ಮತ್ತು AI ಸಮ್ಮತಿ ನೀತಿಯಲ್ಲಿ ವಿವರಿಸಿದಂತೆ ತರಬೇತಿ ಮತ್ತು ವಿಶ್ಲೇಷಣೆಗಳ ಬಳಕೆಗಳಿಗೆ ಸ್ಪಷ್ಟವಾದ ಆಯ್ಕೆಯ ಅಗತ್ಯವಿರುತ್ತದೆ.';

  @override
  String get legalTermsDataConsentLink => 'ಡೇಟಾ ಮತ್ತು AI ಸಮ್ಮತಿ ನೀತಿ';

  @override
  String get legalTermsDataHeading => '5. ಡೇಟಾ ಮತ್ತು ಗೌಪ್ಯತೆ';

  @override
  String get legalTermsDataPrivacyLink => 'ಗೌಪ್ಯತೆ ನೀತಿ';

  @override
  String get legalTermsDefinitionsBody =>
      '\"ಪ್ಲಾಟ್‌ಫಾರ್ಮ್\" ಎಂದರೆ umbrella.okaylegal.ai ಮತ್ತು ಎಲ್ಲಾ ಸಂಬಂಧಿತ ಅಪ್ಲಿಕೇಶನ್‌ಗಳು, APIಗಳು ಮತ್ತು ಸೇವೆಗಳು. \"ಗ್ರಾಹಕ ಬಳಕೆದಾರ\" ಎಂದರೆ ತಮ್ಮದೇ ಆದ ಕಾನೂನು ಪರಿಸ್ಥಿತಿಯನ್ನು ಅರ್ಥಮಾಡಿಕೊಳ್ಳಲು ವೇದಿಕೆಯನ್ನು ಬಳಸುವ ನೈಸರ್ಗಿಕ ವ್ಯಕ್ತಿ. \"ವಕೀಲ ಬಳಕೆದಾರ\" ಎಂದರೆ ಲಾಯರ್ ಓಎಸ್ ವೈಶಿಷ್ಟ್ಯಗಳನ್ನು ಬಳಸಿಕೊಂಡು ಪರವಾನಗಿ ಪಡೆದ ಕಾನೂನು ವೃತ್ತಿಪರ. \"ಹಿಡುವಳಿದಾರ\" ಎಂದರೆ ಕಾನೂನು ಸಂಸ್ಥೆ ಅಥವಾ ಸಂಸ್ಥೆಯ ಚಂದಾದಾರಿಕೆ ಹೊಂದಿರುವ ಸಂಸ್ಥೆ. \"AI ಔಟ್‌ಪುಟ್\" ಎಂದರೆ ಅಂಬ್ರೆಲ್ಲಾದ AI ವ್ಯವಸ್ಥೆಗಳಿಂದ ರಚಿಸಲಾದ ಯಾವುದೇ ಪಠ್ಯ, ವಿಶ್ಲೇಷಣೆ, ಕರಡು ಅಥವಾ ಶಿಫಾರಸು. \"ಮ್ಯಾಟರ್\" ಎಂದರೆ ಲಾಯರ್ ಓಎಸ್ ಮೂಲಕ ನಿರ್ವಹಿಸಲಾದ ಕಾನೂನು ಪ್ರಕರಣ ಅಥವಾ ವಹಿವಾಟು. \"DVTech ವೆಂಚರ್ಸ್\" ಅಥವಾ \"ನಾವು\" ಎಂದರೆ ಪ್ಲಾಟ್‌ಫಾರ್ಮ್‌ನ ಆಪರೇಟರ್.';

  @override
  String get legalTermsDefinitionsHeading => '2. ವ್ಯಾಖ್ಯಾನಗಳು';

  @override
  String get legalTermsDescription =>
      'ಅಂಬ್ರೆಲಾ ಗ್ರಾಹಕ ಮತ್ತು ವಕೀಲ ವೇದಿಕೆಗಳನ್ನು ಬಳಸುವ ನಿಯಮಗಳು.';

  @override
  String get legalTermsDisputeBody =>
      'ಭಾರತದ ಬಳಕೆದಾರರು: ಈ ನಿಯಮಗಳನ್ನು ಭಾರತದ ಕಾನೂನುಗಳಿಂದ ನಿಯಂತ್ರಿಸಲಾಗುತ್ತದೆ; ಬೆಂಗಳೂರಿನಲ್ಲಿ ಕುಳಿತು ಮಧ್ಯಸ್ಥಿಕೆ ಮತ್ತು ರಾಜಿ ಕಾಯಿದೆ 1996 ರ ಅಡಿಯಲ್ಲಿ ಮಧ್ಯಸ್ಥಿಕೆಯನ್ನು ಬಂಧಿಸುವ ಮೂಲಕ ವಿವಾದಗಳನ್ನು ಪರಿಹರಿಸಲಾಗುತ್ತದೆ. ಯುನೈಟೆಡ್ ಸ್ಟೇಟ್ಸ್ ಬಳಕೆದಾರರು: ವಿವಾದಗಳನ್ನು ಡೆಲವೇರ್‌ನಲ್ಲಿ ಕುಳಿತಿರುವ AAA ವಾಣಿಜ್ಯ ಮಧ್ಯಸ್ಥಿಕೆ ನಿಯಮಗಳ ಅಡಿಯಲ್ಲಿ ಬಂಧಿಸುವ ಮಧ್ಯಸ್ಥಿಕೆಯಿಂದ ಪರಿಹರಿಸಲಾಗುತ್ತದೆ; ವರ್ಗ ಕ್ರಿಯೆ ಮನ್ನಾ ಅನ್ವಯಿಸುತ್ತದೆ. ಕೀನ್ಯಾ ಬಳಕೆದಾರರು: ಈ ನಿಯಮಗಳನ್ನು ಕೀನ್ಯಾದ ಕಾನೂನುಗಳಿಂದ ನಿಯಂತ್ರಿಸಲಾಗುತ್ತದೆ; ವಿವಾದಗಳನ್ನು ನೈರೋಬಿ ಸೆಂಟರ್ ಫಾರ್ ಇಂಟರ್ನ್ಯಾಷನಲ್ ಆರ್ಬಿಟ್ರೇಶನ್ (NCIA) ನಿಯಮಗಳ ಅಡಿಯಲ್ಲಿ ಪರಿಹರಿಸಲಾಗುತ್ತದೆ. ಯುನೈಟೆಡ್ ಕಿಂಗ್‌ಡಮ್ ಬಳಕೆದಾರರು: ಈ ನಿಯಮಗಳನ್ನು ಇಂಗ್ಲಿಷ್ ಕಾನೂನಿನಿಂದ ನಿಯಂತ್ರಿಸಲಾಗುತ್ತದೆ; ವಿವಾದಗಳನ್ನು ಇಂಗ್ಲೆಂಡ್ ಮತ್ತು ವೇಲ್ಸ್ ನ್ಯಾಯಾಲಯಗಳ ವಿಶೇಷ ನ್ಯಾಯವ್ಯಾಪ್ತಿಗೆ ಸಲ್ಲಿಸಲಾಗುತ್ತದೆ. ಎಲ್ಲಾ ಸಂದರ್ಭಗಳಲ್ಲಿ, ಸಮರ್ಥ ನ್ಯಾಯಾಲಯದಿಂದ ತುರ್ತು ತಡೆಯಾಜ್ಞೆ ಪರಿಹಾರವನ್ನು ಪಡೆಯಲು ಯಾವುದೂ ನಿಮ್ಮನ್ನು ತಡೆಯುವುದಿಲ್ಲ.';

  @override
  String get legalTermsDisputeHeading => '18. ವಿವಾದ ಪರಿಹಾರ ಮತ್ತು ಆಡಳಿತ ಕಾನೂನು';

  @override
  String get legalTermsIPContentBody =>
      'ನೀವು ಪ್ಲಾಟ್‌ಫಾರ್ಮ್‌ಗೆ ಸಲ್ಲಿಸುವ ಎಲ್ಲಾ ವಿಷಯಗಳ ಮಾಲೀಕತ್ವವನ್ನು ನೀವು ಉಳಿಸಿಕೊಳ್ಳುತ್ತೀರಿ. ವಿಷಯವನ್ನು ಸಲ್ಲಿಸುವ ಮೂಲಕ ನೀವು DVTech ವೆಂಚರ್‌ಗಳಿಗೆ ವಿಶ್ವಾದ್ಯಂತ, ರಾಯಧನ-ಮುಕ್ತ, ಸೇವೆಗಳನ್ನು ತಲುಪಿಸಲು ನಿಮ್ಮ ವಿಷಯವನ್ನು ಪ್ರಕ್ರಿಯೆಗೊಳಿಸಲು, ಸಂಗ್ರಹಿಸಲು ಮತ್ತು ಪ್ರದರ್ಶಿಸಲು ವಿಶೇಷವಲ್ಲದ ಪರವಾನಗಿಯನ್ನು ನೀಡುತ್ತೀರಿ. ಡೇಟಾ ಮತ್ತು AI ಸಮ್ಮತಿ ನೀತಿಯ ಅಡಿಯಲ್ಲಿ ನೀವು ಆಯ್ಕೆ ಮಾಡದ ಹೊರತು ಈ ಪರವಾನಗಿ AI ತರಬೇತಿಗೆ ವಿಸ್ತರಿಸುವುದಿಲ್ಲ.';

  @override
  String get legalTermsIPHeading => '12. ಬೌದ್ಧಿಕ ಆಸ್ತಿ';

  @override
  String get legalTermsIPPlatformBody =>
      'DVTech ವೆಂಚರ್ಸ್ ಅಂಬ್ರೆಲಾ ಪ್ಲಾಟ್‌ಫಾರ್ಮ್, ಬ್ರ್ಯಾಂಡ್, ಆಧಾರವಾಗಿರುವ AI ಮಾದರಿಗಳು ಮತ್ತು ತಂತ್ರಜ್ಞಾನದಲ್ಲಿ ಎಲ್ಲಾ ಹಕ್ಕುಗಳನ್ನು ಹೊಂದಿದೆ. ನಿಮ್ಮ ಚಂದಾದಾರಿಕೆಯ ಅವಧಿಯವರೆಗೆ ಪ್ಲಾಟ್‌ಫಾರ್ಮ್ ಅನ್ನು ಬಳಸಲು ನಿಮಗೆ ಸೀಮಿತ, ವಿಶೇಷವಲ್ಲದ, ವರ್ಗಾವಣೆ ಮಾಡಲಾಗದ ಪರವಾನಗಿಯನ್ನು ನೀಡಲಾಗಿದೆ.';

  @override
  String get legalTermsIndemnityBody =>
      'ನಿರುಪದ್ರವಿ DVTech ವೆಂಚರ್‌ಗಳು ಮತ್ತು ಅದರ ಅಧಿಕಾರಿಗಳು, ನಿರ್ದೇಶಕರು, ಉದ್ಯೋಗಿಗಳು ಮತ್ತು ಏಜೆಂಟರುಗಳಿಂದ ಉಂಟಾಗುವ ಯಾವುದೇ ಕ್ಲೈಮ್‌ಗಳು, ಹಾನಿಗಳು, ನಷ್ಟಗಳು ಮತ್ತು ವೆಚ್ಚಗಳಿಂದ (ಸಮಂಜಸವಾದ ಕಾನೂನು ಶುಲ್ಕಗಳನ್ನು ಒಳಗೊಂಡಂತೆ) ನಷ್ಟವನ್ನು ತುಂಬಲು, ರಕ್ಷಿಸಲು ಮತ್ತು ಹಿಡಿದಿಡಲು ನೀವು ಒಪ್ಪುತ್ತೀರಿ: (a) ಈ ನಿಯಮಗಳನ್ನು ಉಲ್ಲಂಘಿಸಿ ನಿಮ್ಮ ಪ್ಲಾಟ್‌ಫಾರ್ಮ್ ಬಳಕೆ; (ಬಿ) ಯಾವುದೇ ಅನ್ವಯವಾಗುವ ಕಾನೂನಿನ ನಿಮ್ಮ ಉಲ್ಲಂಘನೆ; (ಸಿ) ಮೂರನೇ ವ್ಯಕ್ತಿಯ ಹಕ್ಕುಗಳನ್ನು ಉಲ್ಲಂಘಿಸುವ ನೀವು ಸಲ್ಲಿಸುವ ವಿಷಯ; (ಡಿ) ಪ್ಲಾಟ್‌ಫಾರ್ಮ್ ಅನ್ನು ಬಳಸಿಕೊಂಡು ನಿಮ್ಮ ಗ್ರಾಹಕರಿಗೆ ನೀವು ಒದಗಿಸುವ ಕಾನೂನು ಸಲಹೆ ಅಥವಾ ಸೇವೆಗಳು.';

  @override
  String get legalTermsIndemnityHeading => '17. ನಷ್ಟ ಪರಿಹಾರ';

  @override
  String get legalTermsLawyerUsersBody =>
      'ವಕೀಲ ಬಳಕೆದಾರರು ಸ್ವತಂತ್ರ ಪರವಾನಗಿ ಪಡೆದ ವೃತ್ತಿಪರರು. ವಕೀಲರ OS ಅನ್ನು ಬಳಸುವ ಮೂಲಕ, ನಿಮ್ಮ ಅಧಿಕಾರ ವ್ಯಾಪ್ತಿಯಲ್ಲಿ ನೀವು ಮಾನ್ಯವಾದ ಅಭ್ಯಾಸ ಪ್ರಮಾಣಪತ್ರವನ್ನು ಹೊಂದಿರುವಿರಿ ಮತ್ತು ಅನ್ವಯವಾಗುವ ವೃತ್ತಿಪರ ನಡವಳಿಕೆಯ ನಿಯಮಗಳು ಮತ್ತು ಬಾರ್ ನಿಯಮಗಳಿಗೆ ಅನುಸಾರವಾಗಿ ನೀವು ಪ್ಲಾಟ್‌ಫಾರ್ಮ್ ಅನ್ನು ಬಳಸುತ್ತೀರಿ ಎಂದು ನೀವು ಖಚಿತಪಡಿಸುತ್ತೀರಿ. ನಿಮ್ಮ ಗ್ರಾಹಕರಿಗೆ ನೀವು ಒದಗಿಸುವ ಎಲ್ಲಾ ಕಾನೂನು ಕೆಲಸಗಳು ಮತ್ತು ಸಲಹೆಗಳ ಗುಣಮಟ್ಟ ಮತ್ತು ಕಾನೂನುಬದ್ಧತೆಗೆ ನೀವು ಮಾತ್ರ ಜವಾಬ್ದಾರರಾಗಿರುತ್ತೀರಿ. ಅಂಬ್ರೆಲಾ ಉಪಕರಣಗಳನ್ನು ಒದಗಿಸುತ್ತದೆ - ಇದು ವಕೀಲ ಬಳಕೆದಾರರ ವೃತ್ತಿಪರ ನಡವಳಿಕೆಯನ್ನು ಮೇಲ್ವಿಚಾರಣೆ ಮಾಡುವುದಿಲ್ಲ ಅಥವಾ ಖಾತರಿಪಡಿಸುವುದಿಲ್ಲ.';

  @override
  String get legalTermsLawyerUsersHeading => '11. ವಕೀಲ ಬಳಕೆದಾರರು';

  @override
  String get legalTermsLiabilityBody =>
      'ಕಾನೂನಿನಿಂದ ಅನುಮತಿಸಲಾದ ಗರಿಷ್ಠ ಮಟ್ಟಿಗೆ, AI ಔಟ್‌ಪುಟ್‌ಗಳ ಆಧಾರದ ಮೇಲೆ ನೀವು ಮಾಡುವ ನಿರ್ಧಾರಗಳಿಗೆ ಅಂಬ್ರೆಲಾ ಜವಾಬ್ದಾರನಾಗಿರುವುದಿಲ್ಲ. ನಿಮ್ಮ ಅಧಿಕಾರ ವ್ಯಾಪ್ತಿಯಲ್ಲಿ ಅರ್ಹ ವಕೀಲರನ್ನು ಸಮಾಲೋಚಿಸಲು ನೀವು ಜವಾಬ್ದಾರರಾಗಿರುತ್ತೀರಿ.';

