  @override
  String get legalTermsPermittedUseBody =>
      'ನೀವು ಪ್ಲಾಟ್‌ಫಾರ್ಮ್ ಅನ್ನು ಬಳಸಬಹುದು: ವೈಯಕ್ತಿಕ ಅಥವಾ ವೃತ್ತಿಪರ ಬಳಕೆಗಾಗಿ AI- ರಚಿತವಾದ ಕಾನೂನು ಮಾಹಿತಿಯನ್ನು ಪಡೆದುಕೊಳ್ಳಿ; ಕಾನೂನು ವಿಷಯಗಳು, ಗ್ರಾಹಕರು, ಬಿಲ್ಲಿಂಗ್ ಮತ್ತು ದಾಖಲೆಗಳನ್ನು ನಿರ್ವಹಿಸಿ (ವಕೀಲ ಓಎಸ್); ಪರವಾನಗಿ ಪಡೆದ ವಕೀಲರೊಂದಿಗೆ ಸಂಪರ್ಕಿಸಲು ವಕೀಲ ಮಾರುಕಟ್ಟೆಯನ್ನು ಪ್ರವೇಶಿಸಿ; ಮತ್ತು ನಮ್ಮ ದಾಖಲಿತ API ಮೂಲಕ ನಿಮ್ಮ ಸಿಸ್ಟಮ್‌ಗಳೊಂದಿಗೆ ಪ್ಲಾಟ್‌ಫಾರ್ಮ್ ಅನ್ನು ಸಂಯೋಜಿಸಿ.';

