  @override
  String get legalTermsProhibitedUseBody =>
      'ನೀವು ಮಾಡಬಾರದು: (ಎ) ವಕೀಲರು, ನ್ಯಾಯಾಧೀಶರು ಅಥವಾ ಸರ್ಕಾರಿ ಅಧಿಕಾರಿಯಂತೆ ನಟಿಸುವುದು; (ಬಿ) ವಕೀಲರ ಪರಿಶೀಲನೆಯಿಲ್ಲದೆ ಮೂರನೇ ವ್ಯಕ್ತಿಗಳಿಗೆ ಔಪಚಾರಿಕ ಕಾನೂನು ಸಲಹೆಯಾಗಿ AI ಔಟ್‌ಪುಟ್‌ಗಳನ್ನು ಬಳಸಿ; (ಸಿ) ಕಾನೂನುಬಾಹಿರ, ಮಾನಹಾನಿಕರ ಅಥವಾ ಮೋಸದ ವಿಷಯವನ್ನು ಸಲ್ಲಿಸಿ; (ಡಿ) ಆಧಾರವಾಗಿರುವ AI ಮಾದರಿಗಳು ಅಥವಾ ತರಬೇತಿ ಡೇಟಾವನ್ನು ರಿವರ್ಸ್-ಎಂಜಿನಿಯರ್ ಮಾಡಲು, ಸ್ಕ್ರ್ಯಾಪ್ ಮಾಡಲು ಅಥವಾ ಹೊರತೆಗೆಯಲು ಪ್ರಯತ್ನಿಸುವುದು; (ಇ) ಲಿಖಿತ ಒಪ್ಪಿಗೆಯಿಲ್ಲದೆ ಪ್ಲಾಟ್‌ಫಾರ್ಮ್‌ಗೆ ಮರುಮಾರಾಟ ಅಥವಾ ಉಪಪರವಾನಗಿ ಪ್ರವೇಶ; (ಎಫ್) ಡೇಟಾ ರಕ್ಷಣೆ, ಗ್ರಾಹಕ ರಕ್ಷಣೆ ಮತ್ತು ಕಾನೂನು ವೃತ್ತಿಯ ನಿಯಮಗಳನ್ನು ಒಳಗೊಂಡಂತೆ ಅನ್ವಯವಾಗುವ ಕಾನೂನನ್ನು ಉಲ್ಲಂಘಿಸುವ ಯಾವುದೇ ರೀತಿಯಲ್ಲಿ ವೇದಿಕೆಯನ್ನು ಬಳಸಿ; (ಜಿ) ಮೂರನೇ ವ್ಯಕ್ತಿಯ ಬೌದ್ಧಿಕ ಆಸ್ತಿ ಹಕ್ಕುಗಳನ್ನು ಉಲ್ಲಂಘಿಸುವ ವಿಷಯವನ್ನು ಸಲ್ಲಿಸಿ.';

  @override
