  @override
  String get legalTermsRefundBody =>
      'ಖಾತೆ ಸೆಟ್ಟಿಂಗ್‌ಗಳಿಂದ ನೀವು ಯಾವುದೇ ಸಮಯದಲ್ಲಿ ನಿಮ್ಮ ಚಂದಾದಾರಿಕೆಯನ್ನು ರದ್ದುಗೊಳಿಸಬಹುದು. ಪ್ರಸ್ತುತ ಬಿಲ್ಲಿಂಗ್ ಅವಧಿಯ ಕೊನೆಯಲ್ಲಿ ರದ್ದತಿ ಜಾರಿಗೆ ಬರುತ್ತದೆ; ಬಳಕೆಯಾಗದ ಸಮಯಕ್ಕೆ ಯಾವುದೇ ಭಾಗಶಃ ಮರುಪಾವತಿಯನ್ನು ನೀಡಲಾಗುವುದಿಲ್ಲ. ದೋಷದಿಂದ ನಿಮಗೆ ಶುಲ್ಕ ವಿಧಿಸಲಾಗಿದೆ ಎಂದು ನೀವು ಭಾವಿಸಿದರೆ, ಚಾರ್ಜ್ ಮಾಡಿದ 30 ದಿನಗಳಲ್ಲಿ support@odaflow.com ಅನ್ನು ಸಂಪರ್ಕಿಸಿ. ನಾವು ಪರಿಶೀಲಿಸುತ್ತೇವೆ ಮತ್ತು ಸೂಕ್ತವಾದರೆ, ನಮ್ಮ ವಿವೇಚನೆಯಿಂದ ಪರ-ರಟಾ ಮರುಪಾವತಿಯನ್ನು ನೀಡುತ್ತೇವೆ.';

  @override
  String get legalTermsRefundHeading => '8. ಮರುಪಾವತಿ ಮತ್ತು ರದ್ದತಿ';

  @override
  String get legalTermsSeverabilityBody =>
      'ಈ ನಿಯಮಗಳ ಯಾವುದೇ ನಿಬಂಧನೆಯು ಜಾರಿಗೊಳಿಸಲಾಗದು ಎಂದು ಕಂಡುಬಂದರೆ, ಉಳಿದ ನಿಬಂಧನೆಗಳು ಪೂರ್ಣ ಬಲದಲ್ಲಿ ಮುಂದುವರಿಯುತ್ತವೆ. ಯಾವುದೇ ಹಕ್ಕನ್ನು ಜಾರಿಗೊಳಿಸುವಲ್ಲಿ ನಮ್ಮ ವೈಫಲ್ಯವು ಆ ಹಕ್ಕನ್ನು ಬಿಟ್ಟುಕೊಡುವುದಿಲ್ಲ. ಈ ನಿಯಮಗಳು, ಗೌಪ್ಯತೆ ನೀತಿ ಮತ್ತು ಡೇಟಾ ಮತ್ತು AI ಸಮ್ಮತಿ ನೀತಿಯೊಂದಿಗೆ, ಪ್ಲಾಟ್‌ಫಾರ್ಮ್‌ಗೆ ಸಂಬಂಧಿಸಿದಂತೆ ನಿಮ್ಮ ಮತ್ತು DVTech ವೆಂಚರ್‌ಗಳ ನಡುವಿನ ಸಂಪೂರ್ಣ ಒಪ್ಪಂದವನ್ನು ರೂಪಿಸುತ್ತವೆ.';

  @override
  String get legalTermsSeverabilityHeading => '19. ಸಾಮಾನ್ಯ';

  @override
  String get legalTermsSubscriptionBody =>
      'ಪಾವತಿಸಿದ ಯೋಜನೆಗಳನ್ನು ಮಾಸಿಕ ಅಥವಾ ವಾರ್ಷಿಕ ಚಕ್ರದಲ್ಲಿ ಮುಂಚಿತವಾಗಿ ಬಿಲ್ ಮಾಡಲಾಗುತ್ತದೆ. ಚೆಕ್‌ಔಟ್‌ನಲ್ಲಿ ನಿಮ್ಮ ಸ್ಥಳೀಯ ಕರೆನ್ಸಿಯಲ್ಲಿ ಬೆಲೆಗಳನ್ನು ಪ್ರದರ್ಶಿಸಲಾಗುತ್ತದೆ ಮತ್ತು ಅನ್ವಯವಾಗುವ ತೆರಿಗೆಗಳನ್ನು ಒಳಗೊಂಡಿರಬಹುದು. ನವೀಕರಣ ದಿನಾಂಕದ ಮೊದಲು ನೀವು ರದ್ದುಗೊಳಿಸದ ಹೊರತು ಪ್ರತಿ ಬಿಲ್ಲಿಂಗ್ ಅವಧಿಯ ಕೊನೆಯಲ್ಲಿ ಚಂದಾದಾರಿಕೆಗಳು ಸ್ವಯಂ-ನವೀಕರಣಗೊಳ್ಳುತ್ತವೆ. ಪಾವತಿಸಲು ವಿಫಲವಾದರೆ ಪ್ರವೇಶದ ಅಮಾನತು ಅಥವಾ ಮುಕ್ತಾಯಕ್ಕೆ ಕಾರಣವಾಗಬಹುದು.';

