  @override
  String get legalTermsTrialBody =>
      'ಸೈನ್-ಅಪ್‌ನಲ್ಲಿ ನಿರ್ದಿಷ್ಟಪಡಿಸಿದಂತೆ ಹೊಸ ಖಾತೆಗಳಿಗೆ ಉಚಿತ ಪ್ರಯೋಗಗಳು ಲಭ್ಯವಿವೆ. ಪ್ರಾಯೋಗಿಕ ಅವಧಿಯ ಕೊನೆಯಲ್ಲಿ, ಪ್ರಾಯೋಗಿಕ ಅವಧಿ ಮುಗಿಯುವ ಮೊದಲು ನೀವು ರದ್ದುಗೊಳಿಸದ ಹೊರತು ನಿಮ್ಮ ಖಾತೆಯು ಸ್ವಯಂಚಾಲಿತವಾಗಿ ಅನ್ವಯವಾಗುವ ದರದಲ್ಲಿ ಪಾವತಿಸಿದ ಚಂದಾದಾರಿಕೆಗೆ ಪರಿವರ್ತನೆಯಾಗುತ್ತದೆ. ಯಾವುದೇ ಸಮಯದಲ್ಲಿ ಪ್ರಾಯೋಗಿಕ ಕೊಡುಗೆಗಳನ್ನು ಮಾರ್ಪಡಿಸುವ ಅಥವಾ ನಿಲ್ಲಿಸುವ ಹಕ್ಕನ್ನು ನಾವು ಕಾಯ್ದಿರಿಸಿದ್ದೇವೆ.';

