  @override
  String get legalTermsWarrantiesBody =>
      'ನಾವು ಸಮರ್ಥಿಸುತ್ತೇವೆ: (ಎ) ನಾವು ವೇದಿಕೆಯನ್ನು ಸಮಂಜಸವಾದ ಕೌಶಲ್ಯ ಮತ್ತು ಕಾಳಜಿಯೊಂದಿಗೆ ಒದಗಿಸುತ್ತೇವೆ; (ಬಿ) ನಾವು ವಾಣಿಜ್ಯಿಕವಾಗಿ ಸಮಂಜಸವಾದ ಭದ್ರತಾ ಅಭ್ಯಾಸಗಳನ್ನು ನಿರ್ವಹಿಸುತ್ತೇವೆ. ಕಾನೂನಿನಿಂದ ಅನುಮತಿಸಲಾದ ಪೂರ್ಣ ಪ್ರಮಾಣದಲ್ಲಿ, ನಿರ್ದಿಷ್ಟ ಉದ್ದೇಶಕ್ಕಾಗಿ ಫಿಟ್‌ನೆಸ್‌ನ ವಾರಂಟಿಗಳಿಲ್ಲದೆಯೇ ಪ್ಲಾಟ್‌ಫಾರ್ಮ್ ಅನ್ನು \"ಇರುವಂತೆ\" ಒದಗಿಸಲಾಗಿದೆ, ಉಲ್ಲಂಘನೆಯಿಲ್ಲದ ಅಥವಾ ಅಡೆತಡೆಯಿಲ್ಲದೆ ಲಭ್ಯವಿದೆ. AI ಔಟ್‌ಪುಟ್‌ಗಳ ನಿಖರತೆ, ಸಂಪೂರ್ಣತೆ ಅಥವಾ ಕರೆನ್ಸಿಯನ್ನು ನಾವು ಖಾತರಿಪಡಿಸುವುದಿಲ್ಲ.';

